#include <stdarg.h>
#include <stdio.h>

int sum_ints(int count, ...) {
    va_list args;
    va_start(args, count);
    int total = 0;
    for (int i = 0; i < count; ++i) total += va_arg(args, int);
    va_end(args);
    return total;
}

int main(void) {
    printf("%d\n", sum_ints(3, 4, 5, 6));
    return 0;
}

#include <stdarg.h>
#include <stdio.h>

double sum_values(int count, ...) {
    va_list args;
    va_start(args, count);
    double total = 0.0;
    for (int i = 0; i < count; ++i) total += va_arg(args, double);
    va_end(args);
    return total;
}

int main(void) {
    printf("%.1f\n", sum_values(2, 1.5f, 2.5));
    return 0;
}
